window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-39501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλαιπωρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 43 na letra τ · nº geral 39501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trabalho forçado, penoso 2 pena; fadiga; sofrimento 3 dor física. 〈ταλαίπωρος〉</p></section></article>\n<article id=\"entry-dgp-39502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλαίπωρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 44 na letra τ · nº geral 39502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que experimenta sofrimento físico ou moral; infeliz; mísero 2 cansativo; pensoso. 〈τλῆναι, πῶρος〉</p></section></article>\n<article id=\"entry-dgp-39503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλαιπώρως</h1><div class=\"entry-meta\"><span>DGP · ordem 45 na letra τ · nº geral 39503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. penosamente; miseravelmente.</p></section></article>\n<article id=\"entry-dgp-39504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλαίφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 46 na letra τ · nº geral 39504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος resistente à fadiga, ao infortúnio; paciente; tolerante. 〈τλῆναι, φρήν〉</p></section></article>\n<article id=\"entry-dgp-39505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλακάρδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 47 na letra τ · nº geral 39505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cuja alma resiste à fadiga, ao infortúnio; forte; corajoso 2 desgraçado; infeliz. 〈τλῆναι, καρδία〉</p></section></article>\n<article id=\"entry-dgp-39506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάλαν</h1><div class=\"entry-meta\"><span>DGP · ordem 48 na letra τ · nº geral 39506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">n. e voc. de τάλας.</p></section></article>\n<article id=\"entry-dgp-39507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλανίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 49 na letra τ · nº geral 39507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">considerar infeliz; deplorar; lastimar. 〈τάλας〉</p></section></article>\n<article id=\"entry-dgp-39508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλάντατος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 50 na letra τ · nº geral 39508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. de τάλας.</p></section></article>\n<article id=\"entry-dgp-39509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλαντεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 51 na letra τ · nº geral 39509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 balançar; manter em equilíbrio: τ. ἑαυτὸν ἐφ᾽ ἑκάτερον ὦμον hel. balançar-se suspenso pelos ombros 2 ver oscilar; ver suspenso: τ. τὴν σφαγὴν ἐν ὀφθαλμοῖς hel. manter a morte suspensa diante dos olhos 3 pesar; apreciar; avaliar: τούτων σὺ τὴν αἵρησιν ταλάντευε alcífr. pesa tua opção por essas coisas 4 pender; sofrer inclinação (como prato de balança), para, dat.: τῇ μὲν ἐταλάντευε τὸ ἕλεος, τῇ δ᾽ ἀντέβριθεν ὁ νόμος fíl. a piedade pendia para um lado, mas a lei pendia para o outro ♦ pas. 5 ser mantido em suspenso: τ. ἱσορρόπως luc. estar em equilíbrio 6 estar indeterminado, indeciso: ἐταλαντεύετο ἡ μάχη plut. o combate estava indeciso, incerto 7 ser inclinado; pender como prato de balança: τὸ ζῆν ὑπὸ τούτοις οὐ ταλαντεύεται alcífr. para eles a vida não tinha peso, i.e., não tinha valor 8 oscilar: διὰ τὸ ταλαντεύεσθαι δεῦρο κἀκεῖσε artt. pelo fato de [o mar] oscilar para cá e para lá. 〈τάλαντον〉</p></section></article>\n<article id=\"entry-dgp-39510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλαντιαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 52 na letra τ · nº geral 39510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que pesa 1 talento, aprox. 30 gr. 2 que vale 1 talento (casa) 3 no valor de 1 talento (garantia) 4 que possui 1 talento. 〈τάλαντον〉</p></section></article>\n<article id=\"entry-dgp-39511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάλαντον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 53 na letra τ · nº geral 39511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 prato de balança 2 sing. ou pl. os pratos da balança; balança 3 em Hom., talento, peso e valor em ouro 4 em Atenas, peso legal de 60 minas (= aprox. 26 quilos) 5 talento, soma de prata ou de ouro, de valor variável conforme as cidades e as épocas; em Atenas, o talento somava 60 minas. 〈τλῆναι〉</p></section></article>\n<article id=\"entry-dgp-39512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταλαός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 54 na letra τ · nº geral 39512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Talau, herói mítico.</p></section></article>\n<article id=\"entry-dgp-39513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλαπείριος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 55 na letra τ · nº geral 39513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que sofreu muitas provas; que padeceu muito; desgraçado 2 aventureiro; vagabundo; errante. 〈τλῆναι, πεῖρα〉</p></section></article>\n<article id=\"entry-dgp-39514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλαπενθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 56 na letra τ · nº geral 39514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que suporta aflição; habituado à dor 2 doloroso; penoso (coisa). 〈τλῆναι, πένθος〉</p></section></article>\n<article id=\"entry-dgp-39515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάλαρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 57 na letra τ · nº geral 39515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cesto de fiandeiras 2 cesta para colheita de flores ou frutos 3 recipiente de junco para queijo 4 gaiola para pássaros. 〈τλῆναι〉</p></section></article>\n<article id=\"entry-dgp-39516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάλας, τάλαινα</h1><div class=\"entry-meta\"><span>DGP · ordem 58 na letra τ · nº geral 39516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, poét., τάλας, τάλαν gen. τάλανος, ταλαίνης, τάλανος, voc. τάλαν, τάλαινα, τάλαν (superl. ταλάντατος) 1 que suporta males; infeliz; desafortunado: οἲ᾽ γὼ τάλαινα ξυμφορᾶς κακῆς ésql. infeliz que sou! que funesto acontecimento! τάλαιν᾽ ἐγὼ τῆς ὕβρεως ar. pobre de mim! que ultraje sofri! 2 pejor., miserável 3 penoso; aflitivo; digno de compaixão (coisa). 〈τλῆναι〉</p></section></article>\n<article id=\"entry-dgp-39517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλασία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 59 na letra τ · nº geral 39517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arte de trabalhar a lã; ofício de fiandeira. 〈τλῆναι〉</p></section></article>\n<article id=\"entry-dgp-39518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλάσιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 60 na letra τ · nº geral 39518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">relativo à arte de fiar ou ao trabalho com a lã. 〈τλῆναι〉</p></section></article>\n<article id=\"entry-dgp-39519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλασιουργέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 61 na letra τ · nº geral 39519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fiar a lã. 〈ταλασιουργός〉</p></section></article>\n<article id=\"entry-dgp-39520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλασιουργικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 62 na letra τ · nº geral 39520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">relativo à arte de fiar a lã. 〈ταλασιουργός〉</p></section></article>\n<article id=\"entry-dgp-39521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλασιουργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 63 na letra τ · nº geral 39521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que trabalha ou fia a lã. 〈ταλασία, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-39522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλασίφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 64 na letra τ · nº geral 39522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος de alma forte; paciente. 〈τλῆναι, φρήν〉</p></section></article>\n<article id=\"entry-dgp-39523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλαύρινος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 65 na letra τ · nº geral 39523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 portador de escudo de couro, i.e., invencível; indomável ♦ ταλαύρινον adv. 2 com força invencível. 〈τάλας, ῥινός〉</p></section></article>\n<article id=\"entry-dgp-39524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλάφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 66 na letra τ · nº geral 39524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος = ταλασίφρων.</p></section></article>\n<article id=\"entry-dgp-39525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἄλγος</h1><div class=\"entry-meta\"><span>DGP · ordem 67 na letra τ · nº geral 39525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase póet. de τὸ ἄλγος.</p></section></article>\n<article id=\"entry-dgp-39526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀληθές</h1><div class=\"entry-meta\"><span>DGP · ordem 68 na letra τ · nº geral 39526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὰ ἀληθές.</p></section></article>\n<article id=\"entry-dgp-39527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταλθύβιος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 69 na letra τ · nº geral 39527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Taltíbio, n. de h.</p></section></article>\n<article id=\"entry-dgp-39528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταλίκος, ταλικοῦτος</h1><div class=\"entry-meta\"><span>DGP · ordem 70 na letra τ · nº geral 39528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = τηλίκος, τηλικοῦτος.</p></section></article>\n<article id=\"entry-dgp-39529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τᾶλις, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 71 na letra τ · nº geral 39529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">donzela núbil.</p></section></article>\n<article id=\"entry-dgp-39530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἄλλα</h1><div class=\"entry-meta\"><span>DGP · ordem 72 na letra τ · nº geral 39530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὰ ἄλλα.</p></section></article>\n<article id=\"entry-dgp-39531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀμά</h1><div class=\"entry-meta\"><span>DGP · ordem 73 na letra τ · nº geral 39531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὰ ἐμά.</p></section></article>\n<article id=\"entry-dgp-39532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἄματα</h1><div class=\"entry-meta\"><span>DGP · ordem 74 na letra τ · nº geral 39532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase dór. de τὰ ἤματα.</p></section></article>\n<article id=\"entry-dgp-39533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμέειν</h1><div class=\"entry-meta\"><span>DGP · ordem 75 na letra τ · nº geral 39533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 poét. de τέμνω.</p></section></article>\n<article id=\"entry-dgp-39534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἄμεινον</h1><div class=\"entry-meta\"><span>DGP · ordem 76 na letra τ · nº geral 39534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὸ ἄμεινον.</p></section></article>\n<article id=\"entry-dgp-39535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμεῖον</h1><div class=\"entry-meta\"><span>DGP · ordem 77 na letra τ · nº geral 39535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ταμιεῖον.</p></section></article>\n<article id=\"entry-dgp-39536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμέσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 78 na letra τ · nº geral 39536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 méd. de τέμνω.</p></section></article>\n<article id=\"entry-dgp-39537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμεσίχρως, οος</h1><div class=\"entry-meta\"><span>DGP · ordem 79 na letra τ · nº geral 39537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que corta a pele; que dilacera o corpo. 〈ταμεῖν, χρώς〉</p></section></article>\n<article id=\"entry-dgp-39538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάμῃσι</h1><div class=\"entry-meta\"><span>DGP · ordem 80 na letra τ · nº geral 39538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor.2 subj. de τέμνω.</p></section></article>\n<article id=\"entry-dgp-39539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 81 na letra τ · nº geral 39539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 despenseira; intendente ♦ adj. 2 dispensadora de, gen. 〈τέμνω〉</p></section></article>\n<article id=\"entry-dgp-39540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 82 na letra τ · nº geral 39540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dispensador; distribuidor 2 intendente público; gestor das finanças, em Atenas 3 guarda do tesouro do templo da Acrópole 4 guardião de tesouro 5 em Roma, questor 6 diretor; administrador; árbitro.</p></section></article>\n<article id=\"entry-dgp-39541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμιεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 83 na letra τ · nº geral 39541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 administração 2 economia doméstica 3 tesouraria 4 questura, em Roma. 〈ταμιεύω〉</p></section></article>\n<article id=\"entry-dgp-39542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμιεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 84 na letra τ · nº geral 39542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 local de armazenamento de provisões; despensa; celeiro 2 sede do tesouro público 3 administração do tesouro público 4 em Roma, questura 5 bíbl. aposento recôndito; quarto de dormir. 〈ταμίας〉</p></section></article>\n<article id=\"entry-dgp-39543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμίευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 85 na letra τ · nº geral 39543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 administração doméstica; distribuição das provisões domésticas 2 pl. provisões; abastecimento. 〈ταμιεύω〉</p></section></article>\n<article id=\"entry-dgp-39544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμίευσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 86 na letra τ · nº geral 39544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">partilha; distribuição. 〈ταμιεύω〉</p></section></article>\n<article id=\"entry-dgp-39545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμιευτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 87 na letra τ · nº geral 39545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que sabe administrar; econômico 2 do questor ou da questura ♦ τὸ ταμιευτικόν 3 econo­mia. 〈ταμιεύω〉</p></section></article>\n<article id=\"entry-dgp-39546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμιεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 88 na letra τ · nº geral 39546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. iter. 3a sing. ταμίευσκε, aor. ἐταμίευσα, perf. τεταμίευκα; pas. aor. ἐταμιεύθην, perf. τεταμίευμαι) 1 ser intendente; ser ecônomo de alguém, dat. 2 ser intendente público; administrar os fundos destinados a algo, gen. 3 em Roma, ser questor 4 zelar por; guardar; proteger: Ζηνὸς ταμίευσκε γονάς sóf. [Dânae] zelava pelos filhos de Zeus 5 administrar como intendente; pôr à parte; reservar; depositar: τ. ἐν ἀκροπόλει τὰ ἀριστεῖα τῆς πόλεως dem. depositar na acrópole as contribuições da cidade 6 administrar: χώραν ∆ωριεῖ λαῷ ταμιευομέναν pínd. região administrada pelo povo dório 7 administrar com economia: τ. τἄνδον χρήματα ar. administrar os bens da casa 8 ter controle de, gen. ♦ méd. (fut. ταμιεύσομαι, aor. ἐταμιευσάμην) 9 intr. ser intendente 10 pôr à parte; reservar: ἐς τὸ αὔριον ταμιεύεσθαι τὸ μῖσος luc. reservar seu ódio para o dia seguinte, acumulá-lo até o dia seguinte 11 fazer bom uso; tirar proveito de, ac.: τ. τὴν τύχην ou τὸν καιρόν d.h. aproveitar a sorte, o momento propício 12 calcular com precisão; determinar: οὐκ ἔστιν ἡμῖν ταμιεύεσθαι ἐς ὅσον βουλόμεθα ἄρχειν tuc. não podemos calcular com precisão até onde queremos estender nosso império. 〈ταμία〉</p></section></article>\n<article id=\"entry-dgp-39547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμίη</h1><div class=\"entry-meta\"><span>DGP · ordem 89 na letra τ · nº geral 39547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ταμία.</p></section></article>\n<article id=\"entry-dgp-39548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμίης</h1><div class=\"entry-meta\"><span>DGP · ordem 90 na letra τ · nº geral 39548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ταμίας.</p></section></article>\n<article id=\"entry-dgp-39549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάμνω</h1><div class=\"entry-meta\"><span>DGP · ordem 91 na letra τ · nº geral 39549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e dór. = τέμνω.</p></section></article>\n<article id=\"entry-dgp-39550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμῷ, ταμῇς, ταμῇ</h1><div class=\"entry-meta\"><span>DGP · ordem 92 na letra τ · nº geral 39550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 subj. pas. de τέμνω.</p></section></article>\n<article id=\"entry-dgp-39551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάμω, τάμῃς, τάμῃ</h1><div class=\"entry-meta\"><span>DGP · ordem 93 na letra τ · nº geral 39551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 subj. de τάμνω, jôn. = τέμνω.</p></section></article>\n<article id=\"entry-dgp-39552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμών, οῦσα, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 94 na letra τ · nº geral 39552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 de τέμνω.</p></section></article>\n<article id=\"entry-dgp-39553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀν</h1><div class=\"entry-meta\"><span>DGP · ordem 95 na letra τ · nº geral 39553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. e poét. de τὰ ἐν.</p></section></article>\n<article id=\"entry-dgp-39554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἄν</h1><div class=\"entry-meta\"><span>DGP · ordem 96 na letra τ · nº geral 39554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τοι ἄν.</p></section></article>\n<article id=\"entry-dgp-39555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τᾶν</h1><div class=\"entry-meta\"><span>DGP · ordem 97 na letra τ · nº geral 39555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. pl. beóc. do art. fem. ἡ.</p></section></article>\n<article id=\"entry-dgp-39556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάν</h1><div class=\"entry-meta\"><span>DGP · ordem 98 na letra τ · nº geral 39556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e τᾶν indecl. na loc. ὦ τάν ou ὦ τᾶν meu amigo! meu caro!</p></section></article>\n<article id=\"entry-dgp-39557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τάναγρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 99 na letra τ · nº geral 39557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tânagra, cidade da Beócia.</p></section></article>\n<article id=\"entry-dgp-39558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταναγραϊκή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 100 na letra τ · nº geral 39558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">território de Tânagra. 〈Τάναγρα〉</p></section></article>\n<article id=\"entry-dgp-39559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταναγραῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 101 na letra τ · nº geral 39559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitante ou originário de Tânagra. 〈Τάναγρα〉</p></section></article>\n<article id=\"entry-dgp-39560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταναγρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 102 na letra τ · nº geral 39560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Tânagra. 〈Τάναγρα〉</p></section></article>\n<article id=\"entry-dgp-39561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταναήκης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 103 na letra τ · nº geral 39561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alongado e agudo; pontiagudo; afiado. 〈ταναός, ἀκή〉</p></section></article>\n<article id=\"entry-dgp-39562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀναντία</h1><div class=\"entry-meta\"><span>DGP · ordem 104 na letra τ · nº geral 39562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὰ ἐναντία.</p></section></article>\n<article id=\"entry-dgp-39563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταναός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 105 na letra τ · nº geral 39563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 longo (cabelo) 2 fino e alongado 3 prolongado (som, velhice) 4 que se estende ao longe; vasto; amplo.</p></section></article>\n<article id=\"entry-dgp-39564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταναΰπους, ους, ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 106 na letra τ · nº geral 39564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. -ποδος de pernas longas e delgadas. 〈ταναός, πούς〉</p></section></article>\n<article id=\"entry-dgp-39565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταναϋφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 107 na letra τ · nº geral 39565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de tecido fino e delicado. 〈ταναός, ὑφαίνω〉</p></section></article>\n<article id=\"entry-dgp-39566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἆνδον</h1><div class=\"entry-meta\"><span>DGP · ordem 108 na letra τ · nº geral 39566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὰ ἔνδον.</p></section></article>\n<article id=\"entry-dgp-39567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀνδρός, τἀνδρί</h1><div class=\"entry-meta\"><span>DGP · ordem 109 na letra τ · nº geral 39567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τοῦ ἀνδρός, τῷ ἀνδρί.</p></section></article>\n<article id=\"entry-dgp-39568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανηλεγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 110 na letra τ · nº geral 39568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amargo; cruel; impiedoso, epít. da morte. 〈ταναός, λέγω〉</p></section></article>\n<article id=\"entry-dgp-39569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανίκα</h1><div class=\"entry-meta\"><span>DGP · ordem 111 na letra τ · nº geral 39569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = τηνίκα.</p></section></article>\n<article id=\"entry-dgp-39570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταντάλειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 112 na letra τ · nº geral 39570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Tântalo ♦ ὁ Ταντάλειος 2 filho de Tântalo, Pélops. 〈Τάνταλος〉</p></section></article>\n<article id=\"entry-dgp-39571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τανταλίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 113 na letra τ · nº geral 39571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho de Tântalo. 〈Τάνταλος〉</p></section></article>\n<article id=\"entry-dgp-39572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τάνταλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 114 na letra τ · nº geral 39572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tântalo, n. de heróis míticos.</p></section></article>\n<article id=\"entry-dgp-39573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανταλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 115 na letra τ · nº geral 39573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. aor. pas. τανταλωθείς) fulminar. 〈Τάνταλος〉</p></section></article>\n<article id=\"entry-dgp-39574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀνταῦθα</h1><div class=\"entry-meta\"><span>DGP · ordem 116 na letra τ · nº geral 39574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de τὰ ἐνταῦθα.</p></section></article>\n<article id=\"entry-dgp-39575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀντεῦθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 117 na letra τ · nº geral 39575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de τὰ ἐντεῦθεν.</p></section></article>\n<article id=\"entry-dgp-39576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανύγλωσσος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 118 na letra τ · nº geral 39576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que grasna; grasnante (ave). 〈τανύω, γλῶσσα〉</p></section></article>\n<article id=\"entry-dgp-39577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανυγλώχιν, ινος</h1><div class=\"entry-meta\"><span>DGP · ordem 119 na letra τ · nº geral 39577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de ponta comprida ou alongada. 〈τανύω, γλωχίν〉</p></section></article>\n<article id=\"entry-dgp-39578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανυήκης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 120 na letra τ · nº geral 39578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de ponta longa; agudo; afiado 2 que se alonga; estirado. 〈τανύω, ἀκή〉</p></section></article>\n<article id=\"entry-dgp-39579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάνυμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 121 na letra τ · nº geral 39579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só 3ª sing. τάνυται) estender-se.</p></section></article>\n<article id=\"entry-dgp-39580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανύπεπλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 122 na letra τ · nº geral 39580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de peplo longo; de veste esvoaçante. 〈τανύω, πέπλος〉</p></section></article>\n<article id=\"entry-dgp-39581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανύπους, ποδός</h1><div class=\"entry-meta\"><span>DGP · ordem 123 na letra τ · nº geral 39581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) = ταναΰπους.</p></section></article>\n<article id=\"entry-dgp-39582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανυπτέρυξ, υγος</h1><div class=\"entry-meta\"><span>DGP · ordem 124 na letra τ · nº geral 39582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de asas longas; de asas estendidas. 〈τανύω, πτέρυξ〉</p></section></article>\n<article id=\"entry-dgp-39583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανύσθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 125 na letra τ · nº geral 39583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor. pas. ép. de τανύω.</p></section></article>\n<article id=\"entry-dgp-39584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανυσίπτερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 126 na letra τ · nº geral 39584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">τανυπτέρυξ.</p></section></article>\n<article id=\"entry-dgp-39585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάνυσσα</h1><div class=\"entry-meta\"><span>DGP · ordem 127 na letra τ · nº geral 39585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. poét. de τανύω.</p></section></article>\n<article id=\"entry-dgp-39586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανυστύς, ύος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 128 na letra τ · nº geral 39586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tensão. 〈τανύω〉</p></section></article>\n<article id=\"entry-dgp-39587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανύφλοιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 129 na letra τ · nº geral 39587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de casca comprida 2 de tronco alto e esguio. 〈τανύω, φλοιός〉</p></section></article>\n<article id=\"entry-dgp-39588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανύφυλλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 130 na letra τ · nº geral 39588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de folhas longas 2 frondoso. 〈τανύω, φύλλον〉</p></section></article>\n<article id=\"entry-dgp-39589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανύω</h1><div class=\"entry-meta\"><span>DGP · ordem 131 na letra τ · nº geral 39589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut.τανύσω, aor. ἐτάνυσα, ép. τάνυσσα, perf. desus.; pas. aor. ἐτανύσθην, perf. τετάνυσμαι) 1 estender; estirar com força: τ. βιόν hom. distender um arco, τ. βοείη hom. esticar uma pele de boi, τ. ἶριν hom. estender um arco-íris 2 estender algo: τ. ὀβελούς hom. estender espetos para neles enfiar pedaços de carne, τ. τράπεζαν hom. estender uma mesa, i.e., preparar uma mesa 3 estender alguém; estatelar 4 tornar mais intenso; intensificar (luta, combate) ♦ méd. 5 distender (arco) 6 estar estendido ou alongado; estender-se; alongar-se 7 (cavalo no galope) estender-se com todas as suas forças; lançar-se impetuosamente.</p></section></article>\n<article id=\"entry-dgp-39590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταξιαρχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 132 na letra τ · nº geral 39590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comandar uma companhia ou um batalhão. 〈ταξιάρχης〉</p></section></article>\n<article id=\"entry-dgp-39591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταξιάρχης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 133 na letra τ · nº geral 39591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ταξίαρχος.</p></section></article>\n<article id=\"entry-dgp-39592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταξίαρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 134 na letra τ · nº geral 39592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Mil. taxiarca; comandante de batalhão ou de esquadra 2 em Atenas, comandante de uma divisão de infantaria ou de uma divisão naval 3 comandante de um corpo de cavalaria ♦ em Roma 4 centurião 5 tribuno militar 6 comandante de legião. 〈τάξις, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-39593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταξίλαι, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 135 na letra τ · nº geral 39593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espécie de elefantes corpulentos.</p></section></article>\n<article id=\"entry-dgp-39594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 136 na letra τ · nº geral 39594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Mil. formação; disposição (de tropas) 2 Mil. ordem de batalha 3 Mil. fileira ou linha (de soldados): πρώτη τ. lís. a primeira linha, a linha de frente, a fronte do exército 4 Mil. lugar determinado para cada soldado; posto: ἄναγ᾽ ἐς τάξιν ar. volte para o seu posto, μένειν ἐν τῇ ἑωϋτοῦ τάξει her. permanecer em seu próprio posto, λείπειν ou ἐκλείπειν τὴν τάξιν abandonar seu posto 5 Mil. tropa 6 Mil., em Atenas, tropa de infantaria; companhia; destacamento 7 arranjo; disposição; ordem: τήνδε τὴν τῶν ὅλων τάξιν συνέχουσιν ἀτριβῆ καὶ ἀγήρατον xen. [os deuses] mantém inalterável e imperecível esta disposição de todas as coisas, τ. τοῦ λόγου ésqn. arranjo do discurso 8 constituição política 9 conveniência; decência: διὰ τάξεως plat. com decência 10 condição; estado; função; át. ἐν τάξει na qualidade de, gen.: ἐν ἐχθροῦ τάξει dem. na qualidade de inimigo, como inimigo, ἐν ἐπηρείας τάξει dem. em caráter de insulto 11 disposição; prescrição: τ. τοῦ φόρου xen. taxação do imposto 12 crist. regra (monástica) 13 bíbl. ordem (religiosa). 〈τάσσω〉</p></section></article>\n<article id=\"entry-dgp-39595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταοί</h1><div class=\"entry-meta\"><span>DGP · ordem 137 na letra τ · nº geral 39595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. de ταώς.</p></section></article>\n<article id=\"entry-dgp-39596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 138 na letra τ · nº geral 39596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 baixo; pouco elevado: ταπεινὴ χώρη her. região plana 2 de baixa condição; humilde: ταπεινὰ πράττειν isócr. viver miseravelmente 3 que se humilha; que se rebaixa 4 humilde; modesto 5 baixo; abjeto; vil 6 comum; vulgar; banal: ταπεινὴ λέξις ARTT. estilo simples, sem elevação ♦ τὰ ταπεινά 7 bíbl. planície.</p></section></article>\n<article id=\"entry-dgp-39597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 139 na letra τ · nº geral 39597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pouca altura; baixeza; pequenez 2 pequena estatura 3 condição humilde; humildade 4 falta de coragem; pusilanimidade 5 baixeza de caráter, de sentimentos. 〈ταπεινός〉</p></section></article>\n<article id=\"entry-dgp-39598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινοφροσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 140 na letra τ · nº geral 39598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">humildade; modéstia. 〈ταπεινόφρων〉</p></section></article>\n<article id=\"entry-dgp-39599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινόφρων, ονος</h1><div class=\"entry-meta\"><span>DGP · ordem 141 na letra τ · nº geral 39599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 humilde 2 pusilânime. 〈ταπεινός, φρήν〉</p></section></article>\n<article id=\"entry-dgp-39600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 142 na letra τ · nº geral 39600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 abaixar 2 rebaixar; diminuir 3 aviltar; humilhar 4 bíbl. tornar humilde 5 desencorajar ♦ méd. 6 crist. humilhar ♦ pas. 7 humilhar-se. 〈ταπεινός〉</p></section></article>\n";
